import json
from collections.abc import Mapping

DEFAULTS = {
    "endpoint": "https://localhost",
    "account": "",
    "secret": "",
    "tls": True,
    "output": "text",
    "preview": False,
    "timeout": 30,
    "detail": False,
}

_STRING_KEYS = {"endpoint", "account", "secret", "output"}
_BOOL_KEYS = {"tls", "preview", "detail"}


def parse_config(text):
    if not isinstance(text, str):
        raise ValueError("configuration must be text")
    result = {}
    for number, raw in enumerate(text.splitlines(), 1):
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        if "=" not in line:
            raise ValueError(f"line {number}: missing =")
        key, value = (part.strip() for part in line.split("=", 1))
        if key not in DEFAULTS:
            raise ValueError(f"line {number}: unknown key")
        if key in result:
            raise ValueError(f"line {number}: duplicate key")
        try:
            if key in _STRING_KEYS:
                parsed = json.loads(value)
                if not isinstance(parsed, str):
                    raise ValueError
            elif key in _BOOL_KEYS:
                parsed = value == "true"
            else:
                if not value or any(character not in "0123456789" for character in value):
                    raise ValueError
                parsed = int(value, 10)
        except (ValueError, TypeError, json.JSONDecodeError):
            raise ValueError(f"line {number}: malformed value") from None
        result[key] = parsed
    return result


def validate_config(config):
    if not isinstance(config, Mapping):
        return ("configuration must be a mapping",)
    errors = []
    extra = sorted(set(config) - set(DEFAULTS), key=str)
    if extra:
        errors.append("unknown keys: " + ", ".join(map(str, extra)))
    for key in DEFAULTS:
        if key not in config:
            errors.append(f"missing key: {key}")
            continue
        value = config[key]
        if key == "endpoint" and (
            not isinstance(value, str)
            or not value.startswith(("http://", "https://"))
        ):
            errors.append("endpoint must be an HTTP(S) URL")
        elif key in {"account", "secret"} and not isinstance(value, str):
            errors.append(f"{key} must be a string")
        elif key in _BOOL_KEYS and not isinstance(value, bool):
            errors.append(f"{key} must be a boolean")
        elif key == "output" and (
            not isinstance(value, str) or value not in ("text", "json")
        ):
            errors.append("output must be text or json")
        elif key == "timeout" and (
            isinstance(value, bool)
            or not isinstance(value, int)
            or not 1 <= value <= 300
        ):
            errors.append("timeout must be an integer from 1 through 300")
    return tuple(errors)


def create_config(overrides=None):
    if overrides is None:
        overrides = {}
    if not isinstance(overrides, Mapping):
        raise ValueError("overrides must be a mapping")
    unknown = set(overrides) - set(DEFAULTS)
    if unknown:
        names = sorted(unknown, key=str)
        raise ValueError("unknown override keys: " + ", ".join(map(str, names)))
    config = dict(DEFAULTS)
    config.update(dict(overrides))
    errors = validate_config(config)
    if errors:
        raise ValueError("; ".join(errors))
    lines = []
    for key in DEFAULTS:
        value = config[key]
        if isinstance(value, str):
            rendered = json.dumps(value, ensure_ascii=False)
        elif isinstance(value, bool):
            rendered = "true" if value else "false"
        else:
            rendered = str(value)
        lines.append(f"{key} = {rendered}")
    return "\n".join(lines) + "\n"

